import React from 'react';
import { getContext } from '@fiverr-private/fiverr_context';
import { useWizardContext } from '../WizardContext';
import Step from '../../Stepper/Step';
import Stepper from '../../Stepper';
import type { StepperProps } from '../../Stepper/types';

const WizardStepper = ({
  variant = { default: 'compact', md: 'default' },
  dataTrackTag = 'wizard_stepper',
  dataTrackValue,
}: {
  variant?: StepperProps['variant'];
  dataTrackTag?: StepperProps['dataTrackTag'];
  dataTrackValue?: StepperProps['dataTrackValue'];
}) => {
  const { stepsProps, stepperProps } = useWizardContext();
  const { isMobile } = getContext();

  return !isMobile ? (
    <Stepper dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} variant={variant} stepperProps={stepperProps}>
      {stepsProps?.map(({ key, ...rest }, index) => (
        <Step dataTrackTag={'wizard_stepper_step'} key={key} stepProps={rest}>
          {stepsProps[index].label}
        </Step>
      ))}
    </Stepper>
  ) : null;
};

WizardStepper.displayName = 'WizardStepper';
export default WizardStepper;
