import React from 'react';
import { Button, type ButtonProps } from '@fiverr-private/button';
import { I18n, translate } from '@fiverr-private/i18n-react';
import { useWizardContext } from '../WizardContext';

const WizardFooterSkipButton = ({
  children,
  onClick,
  dataTrackTag = 'wizard_footer_skip_button',
  ...rest
}: Partial<Omit<ButtonProps, 'variant'>>) => {
  const { nextStep, stepStrategy, stepsProps, currentStep } = useWizardContext();
  const handleClick = (e) => {
    nextStep();
    onClick?.(e);
  };

  return stepStrategy === 'cyclic' || stepsProps[currentStep]?.optional ? (
    <Button
      aria-label={translate<string>('navigation.wizard.wizard_footer_skip_button.skip_step')}
      onClick={handleClick}
      variant="ghost"
      dataTrackTag={dataTrackTag}
      {...rest}
    >
      {children || <I18n k="navigation.wizard.wizard_footer_skip_button.skip_step" />}
    </Button>
  ) : null;
};

WizardFooterSkipButton.displayName = 'WizardFooterSkipButton';
export default WizardFooterSkipButton;
