import React from 'react';
import { ProgressLine } from '@fiverr-private/feedback';
import { useWizardContext } from '../WizardContext';

const WizardProgressLine = () => {
  const {
    progressProps: { progressPercent },
  } = useWizardContext();

  return <ProgressLine borderRadius="none" percent={progressPercent} />;
};

WizardProgressLine.displayName = 'WizardProgressLine';
export default WizardProgressLine;
