import React from 'react';
import { Heading, Text } from '@fiverr-private/typography';
import { Stack } from '@fiverr-private/layout_components';

const ContentComponent = ({ index, flow, content }: { index: number; flow?: string; content?: string }) => (
  <Stack direction="column">
    <Heading as="h2">Wizard title - {index + 1}</Heading>
    <Text color="bodySecondary">Wizard subtitle</Text>
    {flow && <Text>{flow.toLocaleLowerCase()}</Text>}
    {content && <Text color="bodySecondary">{content}</Text>}
  </Stack>
);

export default ContentComponent;
