import React, { useEffect } from 'react';
import { ChoiceGroup, ChoiceGroupItem } from '@fiverr-private/forms';
import { Container } from '@fiverr-private/layout_components';
import type { StepperStep } from '../../../../../hooks/useStepper/types';
import ContentComponent from '../ContentComponent';

const moreDynamicSteps: { [k: string]: StepperStep[] } = {
  option_c: [{ stepId: 4, Component: ContentComponent, label: 'Step option C 10' }],
  option_d: [
    { stepId: 2, Component: ContentComponent, label: 'Step option D 10' },
    { stepId: 3, Component: ContentComponent, label: 'Step Option D 11' },
  ],
};

const MoreDynamicSteps = ({
  setUserChoices,
  userChoices,
  currentStep,
  setStepsDataState,
  stepsDataState,
  setDisabled,
}: {
  setUserChoices: React.Dispatch<React.SetStateAction<object>>;
  userChoices: {
    first: undefined | string;
    second: undefined | string;
  };
  currentStep: number;
  setStepsDataState: React.Dispatch<React.SetStateAction<StepperStep[]>>;
  stepsDataState?: any;
  setDisabled: React.Dispatch<React.SetStateAction<boolean>>;
}) => {
  useEffect(() => {
    if (!userChoices?.second) {
      setDisabled?.(true);
    }
    return () => {
      setDisabled?.(false);
    };
  }, [setDisabled, userChoices?.second]);

  return (
    <Container>
      <p>Click to add more dynamic steps</p>
      <ChoiceGroup
        value={userChoices?.second}
        onChange={(newValue) => {
          const updatedSteps: StepperStep[] = [...stepsDataState];
          setDisabled(false);
          if (userChoices.second) {
            const stepsToRemoveCount: StepperStep[] = moreDynamicSteps[userChoices.second] || [];
            updatedSteps.splice(currentStep + 1, stepsToRemoveCount.length);
          }
          setUserChoices({
            ...userChoices,
            second: newValue,
          });
          const stepsToAdd: StepperStep[] = newValue ? moreDynamicSteps[newValue] : [];

          updatedSteps.splice(currentStep + 1, 0, ...stepsToAdd);
          setStepsDataState(updatedSteps);
        }}
      >
        <ChoiceGroupItem value="option_c">Option C</ChoiceGroupItem>
        <ChoiceGroupItem value="option_d">Option D</ChoiceGroupItem>
      </ChoiceGroup>
    </Container>
  );
};

const dynamicSteps: { [k: string]: StepperStep[] } = {
  option_a: [
    { stepId: 3, Component: ContentComponent, label: 'Step option A 3' },
    { stepId: 4, Component: ContentComponent, label: 'Step option A 4' },
    { stepId: 5, Component: MoreDynamicSteps, label: 'Step option A 5' },
    { stepId: 6, Component: ContentComponent, label: 'Step option A 6' },
  ],
  option_b: [
    { stepId: 2, Component: ContentComponent, label: 'Step option B 3' },
    { stepId: 5, Component: MoreDynamicSteps, label: 'Step option A 5' },
    { stepId: 3, Component: ContentComponent, label: 'Step option B 4' },
  ],
};

const DynamicSteps = ({
  initialSteps,
  setUserChoices,
  userChoices,
  currentStep,
  setStepsDataState,
  setDisabled,
}: {
  initialSteps: [];
  setUserChoices: React.Dispatch<React.SetStateAction<object>>;
  userChoices: {
    first: undefined | string;
    second: undefined | string;
  };
  currentStep: number;
  setStepsDataState: React.Dispatch<React.SetStateAction<StepperStep[]>>;
  setDisabled: React.Dispatch<React.SetStateAction<boolean>>;
}) => {
  useEffect(() => {
    if (!userChoices?.first) {
      setDisabled?.(true);
    }
    return () => {
      setDisabled?.(false);
    };
  }, [setDisabled, userChoices?.first]);

  return (
    <Container>
      <p>Click to add dynamic steps</p>
      <ChoiceGroup
        value={userChoices?.first}
        onChange={(newValue) => {
          setDisabled(false);
          setUserChoices({
            first: newValue,
          });
          const stepsToAdd: StepperStep[] = newValue ? dynamicSteps[newValue] : [];
          const updatedSteps: StepperStep[] = [...initialSteps];
          updatedSteps.splice(currentStep + 1, 0, ...stepsToAdd);
          setStepsDataState(updatedSteps);
        }}
      >
        <ChoiceGroupItem value="option_a">Option A</ChoiceGroupItem>
        <ChoiceGroupItem value="option_b">Option B</ChoiceGroupItem>
      </ChoiceGroup>
    </Container>
  );
};

export default DynamicSteps;
