import React from 'react';
import { type Types } from '@fiverr-private/theme';
import { Container } from '@fiverr-private/layout_components';

const WizardBody = ({
  children,
  dataTrackTag = 'wizard_body',
  ...rest
}: Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> & Types.ContainerProps) => (
  <Container dataTrackTag={dataTrackTag} overflowY="scroll" flex={1} {...rest}>
    {children}
  </Container>
);

WizardBody.displayName = 'WizardBody';
export default WizardBody;
