import React, { ReactNode } from 'react';
import { type Types } from '@fiverr-private/theme';
import { Portal } from '@fiverr-private/ui_utils';
import { Container } from '@fiverr-private/layout_components';
import { useKeyboardShortcuts, useLockBodyScroll } from '@fiverr-private/hooks';
import { useWizardContext } from '../WizardContext';

interface wizardContentProps extends Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  children: ReactNode | ReactNode[];
}

const WizardContent = ({ children, dataTrackTag = 'wizard_content', dataTrackValue }: wizardContentProps) => {
  const { isOpen, close } = useWizardContext();
  useLockBodyScroll(isOpen);
  useKeyboardShortcuts([
    {
      trigger: ['Escape'],
      handler: () => close(),
    },
  ]);

  return isOpen ? (
    <Portal>
      <Container
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        display="flex"
        direction="column"
        top={0}
        bottom={0}
        left={0}
        right={0}
        backgroundColor="white"
        position="fixed"
        zIndex="overlay"
      >
        {children}
      </Container>
    </Portal>
  ) : null;
};

WizardContent.displayName = 'WizardContent';
export default WizardContent;
