import { getContext } from '@fiverr-private/fiverr_context';
import { z } from '@fiverr-private/forms';
import { useConst, useElementSize } from '@fiverr-private/hooks';
import { setFiverrContext } from '@fiverr-private/storybook_helpers';

const mobileContext = {
  userAgent:
    'Mozilla/5.0 (Linux; U; Android 4.4.2; en-us; SCH-I535 Build/KOT49H) AppleWebKit/534.30 (KHTML, like Gecko) Version/4.0 Mobile Safari/534.30',
  isTouch: true,
  isMobile: true,
};

export const useSetMobileContext = (customContext = mobileContext) => {
  const { width } = useElementSize(window);
  const fiverrContext = useConst(() => getContext());

  if (width < 600) {
    setFiverrContext(customContext);
  } else {
    setFiverrContext(fiverrContext);
  }
};

export const stepsData = [
  { stepId: 1, label: 'Step text 1' },
  { stepId: 2, label: 'Step text 2', optional: true },
  { stepId: 3, label: 'Step text 3' },
  { stepId: 4, label: 'Step text 4' },
];

export const fetchServer = async (username) =>
  new Promise((resolve, reject) => {
    setTimeout(() => {
      if (username === 'username') {
        reject(new Error('This username is already registered. Please try a different one.'));
      } else {
        resolve('The username is available.');
      }
    }, 1000);
  });

export const schema = z.object({
  username: z.string().min(2, { message: 'username must contain at least 2 character(s)' }),
});

export type SchemaType = z.infer<typeof schema>;
