import { createContext, useContext } from 'react';
import type useStepper from '../../../hooks/useStepper';
import type { WizardProps } from '../types';

type WizardContext = ReturnType<typeof useStepper> & {
  open: () => void;
  close: () => void;
  isOpen: boolean;
  onBackButtonClick?: WizardProps['onBackButtonClick'];
};

export const WizardContext = createContext({} as WizardContext);

export const useWizardContext = () => useContext(WizardContext);
