import React, { useState } from 'react';
import {
  Form,
  FormControl,
  FormElement,
  FormHeader,
  FormHelperText,
  FormLabel,
  FormSubtitle,
  Input,
  useForm,
  UseFormReturn,
  zodResolver,
} from '@fiverr-private/forms';
import { Button } from '@fiverr-private/button';
import { FiverrDarkLogo } from '@fiverr-private/visuals';
import useStepper from '../../../../hooks/useStepper';
import WizardBody from '../../WizardBody';
import WizardFooter from '../../WizardFooter';
import WizardFooterContinueButton from '../../WizardFooterContinueButton';
import WizardFooterSkipButton from '../../WizardFooterSkipButton';
import WizardHeader from '../../WizardHeader';
import WizardHeaderExitButton from '../../WizardHeaderExitButton';
import WizardHeaderLogo from '../../WizardHeaderLogo';
import WizardStepper from '../../WizardStepper';
import WizardTrigger from '../../WizardTrigger';
import { fetchServer, schema, SchemaType, stepsData, useSetMobileContext } from '../helpers';
import Wizard from '../..';
import WizardContent from '../../WizardContent';
import { StepperStep } from '../../../../hooks/useStepper/types';
import DynamicSteps from './DynamicSteps';
import ContentComponent from './ContentComponent';

export const FormValidation = ({ methods }: { methods: UseFormReturn<any> }) => (
  <Form id="registrationForm" methods={methods}>
    <FormControl name="username">
      <FormHeader>
        <FormLabel>User Name</FormLabel>
        <FormSubtitle>Set the user name to username to simulate a server validation error. </FormSubtitle>
      </FormHeader>
      <FormElement>
        <Input defaultValue="username" placeholder="username" />
      </FormElement>
      <FormHelperText />
    </FormControl>
  </Form>
);

export const ValidationForm = () => {
  const result = useStepper({
    steps: stepsData,
    stepStrategy: 'linear-back',
    includeOptional: false,
  });

  const [loading, setLoading] = useState(false);
  const methods = useForm<SchemaType>({
    resolver: zodResolver(schema),
  });

  const formOnClick = methods.handleSubmit(async ({ username }) => {
    try {
      setLoading(true);
      await fetchServer(username);
      result.setStepCompleteState(true);
      result.nextStep();
    } catch (error) {
      methods.setError('username', { message: error.message });
    } finally {
      setLoading(false);
    }
  });

  const continueButtonProps =
    result.currentStep === 0
      ? {
          onClick: formOnClick,
          form: 'registrationForm',
        }
      : {
          onClick: () => {
            result.setStepCompleteState(true);
            result.nextStep();
          },
        };

  return (
    <Wizard useStepperResult={result}>
      <WizardTrigger>
        <Button>Open Wizard</Button>
      </WizardTrigger>
      <WizardContent>
        <WizardHeader>
          <WizardHeaderLogo>
            <FiverrDarkLogo size="sm" />
          </WizardHeaderLogo>
          <WizardStepper />
          <WizardHeaderExitButton />
        </WizardHeader>
        <WizardBody display="flex" gap="6" padding="14" direction="column">
          {result.currentStep === 0 ? (
            <FormValidation methods={methods} />
          ) : (
            <ContentComponent {...result.stepsProps[result.currentStep]} />
          )}
        </WizardBody>
        <WizardFooter>
          <WizardFooterSkipButton />
          <WizardFooterContinueButton loading={loading} {...continueButtonProps} />
        </WizardFooter>
      </WizardContent>
    </Wizard>
  );
};

export const Dynamic = () => {
  useSetMobileContext();

  const stepsData: StepperStep[] = [
    { stepId: 1, Component: ContentComponent, label: 'Step 1', optional: true },
    { stepId: 2, Component: DynamicSteps, label: 'Step 2' },
  ];
  const [stepsDataState, setStepsDataState] = useState(stepsData);
  const [disabled, setDisabled] = useState(false);

  const result = useStepper({
    steps: stepsDataState,
    stepStrategy: 'linear-back',
  });
  const [userChoices, setUserChoices] = useState({
    first: null,
    second: null,
  });

  const CurrentStepComponent = stepsDataState[result.currentStep].Component;

  return (
    <Wizard useStepperResult={result}>
      <WizardTrigger>
        <Button>Open Wizard</Button>
      </WizardTrigger>
      <WizardContent>
        <WizardHeader>
          <WizardHeaderLogo>
            <FiverrDarkLogo size="sm" />
          </WizardHeaderLogo>
          <WizardHeaderExitButton />
        </WizardHeader>
        <WizardBody display="flex" gap="6" padding="14" direction="column">
          <CurrentStepComponent
            {...result.stepsProps[result.currentStep]}
            initialSteps={stepsData}
            setStepsDataState={setStepsDataState}
            currentStep={result.currentStep}
            stepsDataState={stepsDataState}
            setUserChoices={setUserChoices}
            userChoices={userChoices}
            setStepCompleteState={result.setStepCompleteState}
            setDisabled={setDisabled}
          />
        </WizardBody>
        <WizardFooter showProgressLine="all-devices">
          <WizardFooterSkipButton />
          <WizardFooterContinueButton
            disabled={disabled}
            onClick={() => {
              result.setStepCompleteState(true);
              result.nextStep();
            }}
          />
        </WizardFooter>
      </WizardContent>
    </Wizard>
  );
};
