import React from 'react';
import { Container, Divider, Stack } from '@fiverr-private/layout_components';
import { getContext } from '@fiverr-private/fiverr_context';
import WizardBackButton from '../WizardBackButton';
import WizardProgressLine from '../WizardProgressLine';
import type { WizardFooterProps } from './types';

const WizardFooter = ({
  children,
  showProgressLine = 'mobile',
  dataTrackTag = 'wizard_footer',
  dataTrackValue,
}: WizardFooterProps) => {
  const { isMobile } = getContext();
  const showProgress = showProgressLine === 'all-devices' || (showProgressLine === 'mobile' && isMobile);

  return (
    <Container dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} width="100%">
      {showProgress ? <WizardProgressLine /> : <Divider />}
      <Stack
        paddingX={{
          default: '6',
          sm: '10',
        }}
        paddingY={{
          default: '4',
          sm: '6',
        }}
      >
        {!isMobile && <WizardBackButton />}
        <Stack
          marginLeft="auto"
          direction={{
            default: 'columnReverse',
            sm: 'row',
          }}
          width={{
            default: '100%',
            sm: 'initial',
          }}
        >
          {children}
        </Stack>
      </Stack>
    </Container>
  );
};

WizardFooter.displayName = 'WizardFooter';
export default WizardFooter;
