import React, { useCallback, useState } from 'react';
import { Container } from '@fiverr-private/layout_components';
import { WizardContext } from './WizardContext';
import type { WizardProps } from './types';

const Wizard = ({
  children,
  useStepperResult,
  autoOpen = false,
  isOpen,
  onClose,
  onOpen,
  onBackButtonClick,
  dataTrackTag = 'wizard',
  dataTrackValue,
}: WizardProps) => {
  const [innerIsOpen, setInnerIsOpen] = useState(autoOpen);

  const close = useCallback(() => {
    setInnerIsOpen(false);
    onClose?.();
  }, [onClose]);

  const open = useCallback(() => {
    setInnerIsOpen(true);
    onOpen?.();
  }, [onOpen]);

  return (
    <WizardContext.Provider
      value={{ ...useStepperResult, isOpen: isOpen ?? innerIsOpen, close, open, onBackButtonClick }}
    >
      <Container
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        overflowY="scroll"
        position="relative"
        backgroundColor="white"
        width="100%"
        height="100%"
      >
        {children}
      </Container>
    </WizardContext.Provider>
  );
};

Wizard.displayName = 'Wizard';
export default Wizard;
