import React from 'react';
import { useWizardContext } from '../WizardContext';
import type { WizardTriggerProps } from './types';

const WizardTrigger = ({
  children,
  as: Element = 'span',
  disabled,
  dataTrackTag = 'wizard_trigger',
  dataTrackValue,
}: WizardTriggerProps) => {
  const { open } = useWizardContext();

  return (
    <Element data-track-tag={dataTrackTag} data-track-value={dataTrackValue} onClick={disabled ? undefined : open}>
      {children}
    </Element>
  );
};

WizardTrigger.displayName = 'WizardTrigger';

export default WizardTrigger;
