import React from 'react';
import { IconButton, TextButton } from '@fiverr-private/button';
import { I18n, translate } from '@fiverr-private/i18n-react';
import { ArrowLeftIcon } from '@fiverr-private/visuals';
import { getContext } from '@fiverr-private/fiverr_context';
import { Center } from '@fiverr-private/layout_components';
import { useWizardContext } from '../WizardContext';

const WizardBackButton = () => {
  const { prevStep, stepStrategy, currentStep, onBackButtonClick } = useWizardContext();
  const { isMobile } = getContext();
  const props = {
    'aria-label': translate<string>('navigation.wizard.wizard_back_button.back'),
    onClick: () => {
      prevStep();
      onBackButtonClick?.();
    },
  };

  return (
    <Center visibility={stepStrategy === 'linear' || currentStep === 0 ? 'hidden' : 'visible'}>
      {isMobile ? (
        <IconButton size="sm" variant="ghost" {...props}>
          <ArrowLeftIcon />
        </IconButton>
      ) : (
        <TextButton {...props}>
          <ArrowLeftIcon />
          <I18n k="navigation.wizard.wizard_back_button.back" />
        </TextButton>
      )}
    </Center>
  );
};

WizardBackButton.displayName = 'WizardBackButton';
export default WizardBackButton;
