import React from 'react';
import { TextButton, type TextButtonProps } from '@fiverr-private/button';
import { I18n, translate } from '@fiverr-private/i18n-react';
import { Center } from '@fiverr-private/layout_components';
import { useWizardContext } from '../WizardContext';

const WizardHeaderExitButton = ({
  children,
  onClick,
  dataTrackTag = 'wizard_header_exit_button',
  ...rest
}: Partial<TextButtonProps>) => {
  const { close } = useWizardContext();

  return (
    <Center>
      <TextButton
        aria-label={translate<string>('navigation.wizard.wizard_header_exit_button.exit')}
        onClick={(e) => {
          close();
          onClick?.(e);
        }}
        size={{
          default: 'sm',
          sm: 'md',
        }}
        dataTrackTag={dataTrackTag}
        {...rest}
      >
        {children || <I18n k="navigation.wizard.wizard_header_exit_button.exit" />}
      </TextButton>
    </Center>
  );
};

WizardHeaderExitButton.displayName = 'WizardHeaderExitButton';
export default WizardHeaderExitButton;
