import React from 'react';
import { Text } from '@fiverr-private/typography';
import { I18n } from '@fiverr-private/i18n-react';
import { useWizardContext } from '../WizardContext';

const WizardStepsProgress = () => {
  const { currentStep, stepsProps } = useWizardContext();
  return (
    <Text size="b_xs" color="bodySecondary">
      <I18n
        k="navigation.wizard.wizard_steps_progress.progress_text"
        params={{ currentStep: currentStep + 1, totalSteps: stepsProps.length }}
      />
    </Text>
  );
};

WizardStepsProgress.displayName = 'WizardStepsProgress';
export default WizardStepsProgress;
