import React, { useRef, type ReactNode } from 'react';
import { type Types } from '@fiverr-private/theme';
import { Divider, Stack } from '@fiverr-private/layout_components';
import { getContext } from '@fiverr-private/fiverr_context';
import WizardBackButton from '../WizardBackButton';

interface wizardHeaderProps extends Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  children: ReactNode;
}

const WizardHeader = ({ children }: wizardHeaderProps) => {
  const { isMobile } = getContext();
  const ref = useRef<HTMLDivElement>(null);

  return (
    <Stack direction="column" gap="0">
      <Stack
        ref={ref}
        tabIndex={-1}
        paddingX={{
          default: '6',
          sm: '10',
        }}
        paddingY={{
          default: '4',
          sm: '5',
        }}
        maxHeight="80px"
        justifyContent="spaceBetween"
        alignItems="center"
      >
        {isMobile && <WizardBackButton />}
        {children}
      </Stack>
      <Divider />
    </Stack>
  );
};

WizardHeader.displayName = 'WizardHeader';
export default WizardHeader;
