import React from 'react';
import { Box, type Types } from '@fiverr-private/theme';

const WizardHeaderLogo = ({
  children,
  onClick,
  href,
  dataTrackTag = 'wizard_header_logo',
  dataTrackValue,
}: Pick<Types.BoxType, 'children' | 'href' | 'onClick' | 'dataTrackTag' | 'dataTrackValue'>) => {
  const getElement = () => {
    if (href) {
      return 'a';
    }
    if (onClick) {
      return 'button';
    }
    return 'div';
  };

  return (
    <Box
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      as={getElement()}
      display="flex"
      alignItems="center"
      justifyContent="center"
      outlineColor={{ focusVisible: 'grey_1200' }}
      outlineStyle={{ focusVisible: 'solid' }}
      outlineWidth={{ focusVisible: 'md' }}
      borderRadius="lg"
      padding={{ sm: '2' }}
      flexShrink={0}
    >
      {children}
    </Box>
  );
};

WizardHeaderLogo.displayName = 'WizardHeaderLogo';
export default WizardHeaderLogo;
